import{_t as e,it as t,n,rt as r}from"./chunks/framework.ZiPJV70T.js";var i=JSON.parse(`{"title":"Independent Claude review stage","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/2026-11-23-claude-review-stage.md","filePath":"decisions/2026-11-23-claude-review-stage.md"}`),a={name:`decisions/2026-11-23-claude-review-stage.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="independent-claude-review-stage" tabindex="-1" dir="auto">Independent Claude review stage <a class="header-anchor" href="#independent-claude-review-stage" aria-label="Permalink to “Independent Claude review stage”">​</a></h1><ul><li dir="auto">Status: accepted</li><li dir="auto">Date: 2026-11-23</li></ul><h2 id="context" tabindex="-1" dir="auto">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p dir="auto">Since the Gemini stages were removed (<a href="./2026-10-03-remove-gemini-stages.html">2026-10-03-remove-gemini-stages</a>), a pipeline PR reaches <code>stage:human-approval</code> with only CI and an optional Copilot review. Nothing that did not write the code checks it against the spec, and an agent tends to praise its own work (issue #154).</p><h2 id="decision" tabindex="-1" dir="auto">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p dir="auto">A new stage, <code>review.yml</code>, runs once per head commit of a pipeline PR after CI succeeds. A Claude run with read-only tools (<code>Read</code>, <code>Glob</code>, <code>Grep</code>), a read-only token and the prompt <code>.github/prompts/review.md</code> compares the diff with the issue&#39;s <code>pipeline:spec</code> and <code>pipeline:plan</code> comments, and reports at most 5 findings (requirement, test, correctness, security; never style), each with a file, a line and a concrete failure scenario.</p><ul><li dir="auto">The agent never holds a write token. A deterministic <code>publish</code> job (App token) checks its JSON and posts the findings as review threads (<code>R-&lt;n&gt;</code>), which the existing thread gate and <code>/disposition</code> already handle.</li><li dir="auto">The head&#39;s <code>pipeline/review</code> commit status records the run, so a head is reviewed once. <code>pipeline/gates</code> has a new <strong>Claude review</strong> gate: a pipeline PR waits for <code>pipeline/review</code> = <code>success</code> on its head.</li><li dir="auto">A clean review posts no threads, only an outcome note <code>review: clean</code>; the note re-runs <code>approval.yml</code>.</li><li dir="auto">A failed run sets <code>pipeline/review</code> = <code>failure</code>, appends an outcome note (stage <code>review</code>) and <code>stage:routing</code>; the router hands it to a human. No retry loop and no automatic fixing.</li><li dir="auto">The reviewer does not run <code>pnpm verify</code> (the issue suggested it). CI has already run it on the same commit, and running PR code in a job that holds the OAuth token would break W5 (docs/security.md). For the same reason the PR&#39;s <code>.claude/</code>, <code>.codex/</code> and <code>.mcp.json</code> are deleted before the agent starts.</li></ul><h2 id="consequences" tabindex="-1" dir="auto">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li dir="auto">Every pipeline PR costs one more Claude run per head, and the hand-off waits for it (a few minutes).</li><li dir="auto">The owner fixes or dispositions each finding; a person still reviews and merges.</li><li dir="auto">A failed review parks the PR for a person, who re-runs <strong>Pipeline · Review</strong> by hand (workflow_dispatch). A head with a successful review is never reviewed again, even by hand.</li><li dir="auto"><code>pipeline/review</code> is not a required check of the ruleset: <code>pipeline/gates</code> already sums it up.</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};